-- Node: dm-dka-screen (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"DKA/HHS Screening","body":"**Check for diabetic emergencies before routine hyperglycemia management.**\n\n**DKA criteria — 2024 ADA/EASD consensus (all 3 required):** [1][2]\n- **D (hyperglycemia):** glucose >=200 mg/dL OR known history of diabetes (history allows euglycemic DKA)\n- **K (ketosis):** beta-hydroxybutyrate >=3.0 mmol/L (or ketonuria >=2+)\n- **A (acidosis):** pH <7.3 AND/OR HCO3 <18 mmol/L\n\n*The 2024 consensus REMOVED the anion gap from the diagnostic criteria and uses venous (not arterial) samples. Anion gap remains useful for tracking response but is no longer required for diagnosis.*\n\n**HHS criteria:** [3]\n- Glucose >600 mg/dL\n- Serum osmolality >320 mOsm/kg\n- Minimal/no ketosis\n- pH usually >7.3\n\n**Euglycemic DKA:**\n- SGLT2 inhibitor use (empagliflozin, dapagliflozin, canagliflozin)\n- Can present with glucose 150-250 mg/dL with full DKA\n- Check beta-hydroxybutyrate if SGLT2i and any GI symptoms","citation":[1,2,3],"options":[{"label":"DKA Confirmed or Suspected","description":"Acidosis + ketosis + hyperglycemia","next":"dm-dka-link","urgency":"critical"},{"label":"HHS Suspected","description":"Glucose >600, osmolality >320, no significant ketosis","next":"dm-hhs-management","urgency":"critical"},{"label":"No DKA/HHS - Routine Hyperglycemia","description":"Proceed to inpatient or outpatient pathway","next":"dm-type-assess"}],"summary":"DKA/HHS Screening — assess clinical status to guide next management decision"}'::jsonb
WHERE id = 'dm-dka-screen' AND tree_id = 'diabetes-management';

