UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"DigiFab — Indications","body":"[DigiFab Dosing Calculator](#/calculator/dig-fab-dosing)\n\n**Indications for DigiFab (Digoxin Immune Fab):** [2][3]\n\n**Life-threatening criteria:**\n• Life-threatening arrhythmia (VT, VF, high-grade AV block, symptomatic bradycardia unresponsive to atropine)\n• Hemodynamic instability (hypotension, shock)\n• **K+ >5.5 mEq/L** (in setting of digoxin toxicity)\n\n**Level-based criteria:**\n• Acute ingestion: digoxin level **>10 ng/mL** [3]\n• Chronic toxicity: digoxin level **>6 ng/mL** with symptoms [3]\n\n**Clinical gestalt:**\n• Significant ingestion with cardiac symptoms\n• Progressive toxicity despite supportive care\n• Known massive ingestion (even before symptoms develop)\n\n**Onset of effect:** 30-60 minutes. Clinical improvement may take up to 4 hours [3].\n\n**Half-life:** 15-20 hours (Fab fragments are renally cleared).","citation":[2,3],"next":"dig-fab-dosing","calculatorLinks":[{"id":"dig-fab-dosing","label":"DigiFab Dosing Calculator"}],"summary":"DigiFab — Indications — review key clinical information before proceeding"}'::jsonb
WHERE id = 'dig-fab' AND tree_id = 'digoxin-toxicity';

